def mongo_source(key,operation):
    return "const lab=db.getSiblingDB('atlas_demo_"+key.replace('-','_')+"');\nconst items=lab.getCollection('items');\nitems.drop();\nitems.insertMany("+json.dumps(ITEMS)+");\n"+operation+"\n"

