    first=mongo_source('setup',"printjson({count:items.countDocuments(),database:lab.getName()});")
    book.add("setup","Inizializzare un laboratorio MongoDB locale separato","Avviare manualmente un processo di laboratorio su una porta distinta e inserire tre documenti sintetici.",{"mongod.yaml":config,"demo.js":first},section="Inizializzazione",commands=[{"shell":"PowerShell","os":"Windows","cwd":".","label":"Terminale server dedicato","code":"New-Item -ItemType Directory -Path .mongo-data -Force | Out-Null\nmongod --config mongod.yaml"},{"shell":"PowerShell","os":"Windows","cwd":".","label":"Secondo terminale: client","code":'mongosh "mongodb://127.0.0.1:27018/atlas_demo_setup" --quiet --file demo.js'}],explanation="## Ambiente\nInstalla MongoDB Community8.0 e mongosh2.x. La configurazione usa dati in .mongo-data e soltanto loopback27018; non punta a un servizio esistente. Avvia il server nel primo terminale e lascialo aperto. Esegui il client nel secondo.\n\n## Isolamento\ndemo.js opera soltanto sulla collezione items di atlas_demo_setup e la ricrea, perdendone i dati. I nomi sono riservati al laboratorio. Arresta il processo server con Ctrl+C al termine; il catalogo non lo avvia automaticamente.",expected="Il client stampa count3 e il nome del database didattico.",tags=["mongodb","setup","mongod","mongosh","localhost"])
    schema="const lab=db.getSiblingDB('atlas_demo_schema');lab.inventory.drop();lab.createCollection('inventory',{validator:{$jsonSchema:{bsonType:'object',required:['sku','qty'],properties:{sku:{bsonType:'string'},qty:{bsonType:'number',minimum:0}}}}});lab.inventory.createIndex({sku:1},{unique:true});lab.inventory.insertOne({sku:'keyboard',qty:8});printjson(lab.inventory.find().toArray());"
    book.add("schema-indexes","Versionare schema e indici di una collezione","Conservare validazione JSON Schema e vincoli di unicità in uno script ripetibile.",{"schema.js":schema},section="Configurazione",commands='mongosh "mongodb://127.0.0.1:27018/atlas_demo_schema" --quiet --file schema.js',explanation="## Schema ripetibile\nLo script ricrea soltanto inventory nel database atlas_demo_schema, quindi elimina i dati di quella collezione. La validazione impone sku testuale e quantità numerica non negativa; l'indice univoco protegge il codice.\n\n## Integrazione\nIn una migrazione su dati da conservare non usare drop: pianifica collMod e la pulizia dei dati incompatibili. Questa ricetta è un bootstrap di laboratorio da eseguire su un processo locale dedicato.",expected="La collezione contiene keyboard8 e un indice sku univoco.",tags=["mongodb","schema","validator","index","migration"])
    debug=mongo_source('debug',"items.createIndex({stock:1},{name:'stock_asc'});printjson(items.find({stock:{$gt:0}}).explain('executionStats'));")
    book.add("debug-plan","Diagnosticare una query con executionStats","Confrontare numero di documenti restituiti e letti senza supporre che un indice venga sempre scelto.",{"explain.js":debug},section="Debug",commands='mongosh "mongodb://127.0.0.1:27018/atlas_demo_debug" --quiet --file explain.js',explanation="## Piano reale\nIl laboratorio crea un indice stock e chiama explain executionStats. Esamina nReturned, totalDocsExamined e winningPlan nel formato restituito dal server. Tre documenti non rappresentano un benchmark; il planner può preferire una scansione.\n\n## Limite\nexecutionStats esegue davvero la lettura. Lo script usa solo dati sintetici in un database dal nome dedicato.",expected="Un piano con statistiche reali è stampato dal server locale.",tags=["mongodb","debug","explain","executionStats"])
    tests=mongo_source('tests',"function check(ok,msg){if(!ok)throw new Error(msg);}check(items.countDocuments()===3,'Seed');items.updateOne({_id:1,stock:{$gte:2}},{$inc:{stock:-2}});check(items.findOne({_id:1}).stock===6,'Prenotazione');check(items.updateOne({_id:2,stock:{$gte:1}},{$inc:{stock:-1}}).modifiedCount===0,'Stock esaurito');print('3 controlli superati');")
    book.add("test-lab","Eseguire controlli di regressione sul server di prova","Far terminare lo script con errore quando seed, modifica o protezione dello stock non rispettano le attese.",{"test.js":tests},section="Test",commands='mongosh "mongodb://127.0.0.1:27018/atlas_demo_tests" --quiet --file test.js',explanation="## Controlli\nLo script ricrea i tre documenti e controlla conteggio, decremento di due unità e mancata modifica su stock esaurito. Un throw fa fallire la prova e va trattato come errore del laboratorio.\n\n## Ambiente\nRichiede il server locale separato; la semplice verifica sintattica di JavaScript non equivale a questi test d'integrazione.",expected="Lo script stampa3 controlli superati soltanto dopo le verifiche sul server.",tags=["mongodb","test","integration","stock"])
    book.add("backup","Esportare e ripristinare il solo database didattico","Usare Database Tools per una copia selettiva evitando un dump dell'intero server.",{"README.md":"# Backup laboratorio MongoDB\nRichiede MongoDB Database Tools100.x. Eseguire i comandi solo su atlas_demo_setup del processo locale di prova. Il restore usa un nome nuovo.\n"},section="Distribuzione",commands='mongodump --uri="mongodb://127.0.0.1:27018" --db=atlas_demo_setup --out=backup-demo\nmongorestore --uri="mongodb://127.0.0.1:27018" --nsInclude="atlas_demo_setup.*" --nsFrom="atlas_demo_setup.*" --nsTo="atlas_demo_restored.*" backup-demo',explanation="## Copia selettiva\nIl dump include soltanto atlas_demo_setup. La seconda operazione rimappa il namespace in atlas_demo_restored, da scegliere nuovo e vuoto. Non usa --drop. Verifica dopo il ripristino documenti e indici con mongosh.\n\n## Consegna\nConserva versione degli strumenti e manifest dello schema insieme al backup. Le credenziali non sono incluse nei file del progetto. La ricetta non esegue alcun backup del server dell'utente.",expected="La copia ripristinata è nel namespace atlas_demo_restored, separata dall'origine.",tags=["mongodb","backup","mongodump","mongorestore","namespace"])

