def redis_script(key,body):
    return '#!/usr/bin/env bash\nset -euo pipefail\np="atlas_demo:'+key+'"\ncli(){ redis-cli -e --raw -h 127.0.0.1 -p 6381 "$@"; }\n'+body.replace('redis-cli -h','redis-cli -e --raw -h')+'\n'

def redis_lifecycle(book):
    config='bind 127.0.0.1\nport 6381\ndir ./.redis-data\ndbfilename atlas.rdb\nappendonly yes\n'
    book.add("setup","Inizializzare Redis in un processo locale dedicato","Usare una porta distinta e una directory dati separata in Linux o WSL.",{"redis.conf":config,"check.sh":redis_script('setup','cli PING\ncli SET "$p:hello" world EX 60\ncli GET "$p:hello"')},section="Inizializzazione",os=["Linux"],commands=[{"shell":"Bash","os":"Linux","cwd":".","label":"Terminale server","code":"mkdir -p .redis-data\nredis-server ./redis.conf"},{"shell":"Bash","os":"Linux","cwd":".","label":"Secondo terminale: controllo","code":"bash ./check.sh"}],explanation="## Piattaforma\nInstalla Redis Open Source8.2 e redis-cli in Linux o WSL. La ricetta usa un processo a sé su127.0.0.1:6381 e dati in .redis-data; non richiede Docker Desktop né un pacchetto Windows nativo non ufficiale.\n\n## Avvio\nLascia il server nel primo terminale e usa il secondo per il controllo. PING deve rispondere PONG. Il prefisso atlas_demo distingue le chiavi del laboratorio. Il catalogo non esegue automaticamente questi comandi.",expected="PONG e world nel secondo terminale.",tags=["redis","setup","WSL","redis-server","localhost"])
    book.add("persistence","Configurare persistenza AOF per il laboratorio","Conservare il dataset del processo didattico oltre la sua terminazione.",{"redis.conf":config,'demo.sh':redis_script('persistence','cli SET "$p:message" persistent\ncli INFO persistence')},section="Configurazione",commands=[{"shell":"Bash","os":"Linux","cwd":".","code":"mkdir -p .redis-data\nredis-server ./redis.conf"}],explanation="## Configurazione\nappendonly yes abilita AOF per questo server dedicato. Dopo l'avvio, in un secondo terminale esegui bash demo.sh e leggi INFO persistence. Arresta normalmente il processo e riaprilo con la stessa directory per verificare GET atlas_demo:persistence:message.\n\n## Limiti\nLe garanzie di durabilità dipendono dalla politica appendfsync e dal filesystem; questa guida non dichiara test di perdita di alimentazione.",expected="Dopo un riavvio normale la chiave didattica è nuovamente disponibile.",tags=["redis","AOF","persistence","configuration"])
    book.add("debug","Diagnosticare chiavi e latenza senza cambiare configurazione globale","Interrogare TTL, tipo e statistiche del solo server di prova.",{"debug.sh":redis_script('debug','cli SET "$p:key" value EX 60\ncli TYPE "$p:key"\ncli PTTL "$p:key"\ncli INFO stats\ncli SLOWLOG GET 5')},section="Debug",commands=[{"shell":"Bash","os":"Linux","cwd":".","code":"bash debug.sh"}],explanation="## Lettura\nTYPE controlla il dato prima di scegliere i comandi. PTTL restituisce millisecondi, -1 per chiave senza scadenza e -2 per chiave assente. INFO stats e SLOWLOG GET mostrano dati del processo dedicato; un log vuoto non prova che ogni query sia veloce.\n\n## Ambiente\nNon modifica soglie SLOWLOG o configurazioni di un server esistente.",expected="Tipo string, PTTL positivo e statistiche del processo locale.",tags=["redis","debug","TTL","SLOWLOG","INFO"])
    tests=redis_script('tests','cli DEL "$p:count"\ncli INCRBY "$p:count" 3 >/dev/null\nvalue=$(cli GET "$p:count")\n[[ "$value" == 3 ]] || { printf "Contatore errato\\n" >&2; exit 1; }\ncli EXPIRE "$p:count" 60 >/dev/null\n[[ $(cli TTL "$p:count") -gt 0 ]] || { printf "TTL errato\\n" >&2; exit 1; }\nprintf "2 controlli superati\\n"')
    book.add("test","Eseguire controlli sul dataset di prova Redis","Tradurre un risultato errato in codice di uscita non zero per una regressione automatizzabile.",{"test.sh":tests},section="Test",commands=[{"shell":"Bash","os":"Linux","cwd":".","code":"bash test.sh"}],explanation="## Test d'integrazione\nLo script usa soltanto atlas_demo:tests:count e controlla valore e presenza della scadenza. Richiede il processo dedicato già avviato. Con set -euo pipefail gli errori della shell interrompono il test; le risposte logiche vengono confrontate esplicitamente.\n\n## Attestazione\nUn controllo sintattico bash -n non esegue questi test e non dimostra la disponibilità di Redis.",expected="Sono stampati2 controlli superati solo dopo i confronti.",tags=["redis","test","Bash","TTL"])
    book.add("backup","Creare uno snapshot del solo processo Redis didattico","Usare una connessione locale dedicata per produrre un RDB senza intervenire su database di produzione.",{"README.md":"# Snapshot Redis di laboratorio\nIl server deve essere quello isolato sulla porta6381, contenente solo dati sintetici. Il file contiene l'intero dataset di quel processo, non un filtro per prefisso.\n"},section="Distribuzione",commands=[{"shell":"Bash","os":"Linux","cwd":".","code":"redis-cli -h 127.0.0.1 -p 6381 --rdb atlas-lab.rdb\nredis-check-rdb atlas-lab.rdb"}],explanation="## Ambito\n--rdb trasferisce uno snapshot del processo Redis, quindi include tutte le sue chiavi. Usa soltanto l'istanza di laboratorio separata. redis-check-rdb controlla il formato del file, non le regole applicative dei dati.\n\n## Ripristino\nPer una prova copia il file in una directory nuova e usa un altro processo su una porta libera specificando dir/dbfilename; non sovrascrivere la directory del server sorgente. Nessun ripristino è avviato dal catalogo.",expected="Il file RDB è prodotto e il controllo ne conferma il formato.",tags=["redis","backup","RDB","redis-check-rdb"])

VALIDATION="""export function validSku(value){if(typeof value!=='string'||!/^[a-z][a-z0-9-]{0,39}$/.test(value))throw new Error('SKU non valido');return value;}
export function validCount(value){const n=Number(value);if(!Number.isSafeInteger(n)||n<1)throw new Error('Quantità non valida');return n;}
export function localUrl(value,protocol,port){const url=new URL(value);if(url.protocol!==protocol||!['127.0.0.1','localhost'].includes(url.hostname)||Number(url.port||port)!==port)throw new Error('Usare il processo locale di laboratorio');return value;}
"""
VALIDATION_TEST="""import test from 'node:test';import assert from 'node:assert/strict';import {validSku,validCount,localUrl} from '../model.mjs';
test('SKU e quantità validi',()=>{assert.equal(validSku('keyboard'), 'keyboard');assert.equal(validCount('2'),2);});
test('rifiuta quantità non positive o frazionarie',()=>{for(const v of [0,-1,1.5,'x'])assert.throws(()=>validCount(v));});
test('rifiuta host esterno',()=>assert.throws(()=>localUrl('mongodb://example.invalid:27018','mongodb:',27018)));
"""

def capstone(book,stack):
    if stack=='mongodb':
        package={"name":"atlas-mongo-inventory","version":"1.0.0","private":True,"type":"module","scripts":{"test":"node --test","seed":"node seed.mjs","reserve":"node main.mjs"},"dependencies":{"mongodb":"7.7.0"}}
        db="import {MongoClient} from 'mongodb';import {localUrl} from './model.mjs';export async function connect(){const uri=localUrl(process.env.ATLAS_MONGO_URL||'mongodb://127.0.0.1:27018','mongodb:',27018);const client=new MongoClient(uri,{serverSelectionTimeoutMS:2000});await client.connect();return{client,items:client.db('atlas_capstone_inventory').collection('inventory')};}\n"
        operation="import {validSku,validCount} from './model.mjs';export async function reserve(items,sku,count){sku=validSku(sku);count=validCount(count);const row=await items.findOneAndUpdate({_id:sku,qty:{$gte:count}},{$inc:{qty:-count}},{returnDocument:'after'});if(!row)throw new Error('Stock insufficiente');return row;}\n"
        seed="import {connect} from './db.mjs';const {client,items}=await connect();try{await items.updateOne({_id:'keyboard'},{$setOnInsert:{qty:8}},{upsert:true});console.log(await items.findOne({_id:'keyboard'}));}finally{await client.close();}\n"
    else:
        package={"name":"atlas-redis-inventory","version":"1.0.0","private":True,"type":"module","scripts":{"test":"node --test","seed":"node seed.mjs","reserve":"node main.mjs"},"dependencies":{"redis":"6.3.1"}}
        db="import {createClient} from 'redis';import {localUrl} from './model.mjs';export async function connect(){const uri=localUrl(process.env.ATLAS_REDIS_URL||'redis://127.0.0.1:6381','redis:',6381);const client=createClient({url:uri,socket:{connectTimeout:2000,reconnectStrategy:false}});client.on('error',error=>console.error(error.message));await client.connect();return{client,items:client};}\n"
        operation="import {validSku,validCount} from './model.mjs';const script=\"local current=tonumber(redis.call('GET',KEYS[1]) or '-1');local n=tonumber(ARGV[1]);if current<n then return -1 end;return redis.call('DECRBY',KEYS[1],n)\";export async function reserve(items,sku,count){sku=validSku(sku);count=validCount(count);const qty=await items.eval(script,{keys:['atlas_capstone:stock:'+sku],arguments:[String(count)]});if(Number(qty)<0)throw new Error('Stock insufficiente');return{_id:sku,qty:Number(qty)};}\n"
        seed="import {connect} from './db.mjs';const {client}=await connect();try{await client.set('atlas_capstone:stock:keyboard','8',{NX:true});console.log(await client.get('atlas_capstone:stock:keyboard'));}finally{await client.close();}\n"
    main="import {connect} from './db.mjs';import {reserve} from './stock.mjs';const {client,items}=await connect();try{console.log(await reserve(items,process.argv[2]||'keyboard',process.argv[3]||'1'));}catch(error){console.error(error.message);process.exitCode=1;}finally{await client.close();}\n"
    tests=VALIDATION_TEST+"\nimport {reserve} from '../stock.mjs';test('non chiama lo storage per quantità invalida',async()=>{let called=false;const store={findOneAndUpdate:async()=>{called=true;return null;},eval:async()=>{called=true;return -1;}};await assert.rejects(reserve(store,'keyboard',0));assert.equal(called,false);});test('stock insufficiente non è un risultato valido',async()=>{const store={findOneAndUpdate:async()=>null,eval:async()=>-1};await assert.rejects(reserve(store,'keyboard',1),/insufficiente/);});"
    files={"package.json":js(package),"model.mjs":VALIDATION,"db.mjs":db,"stock.mjs":operation,"seed.mjs":seed,"main.mjs":main,"test/model.test.mjs":tests,"README.md":f"# Magazzino {stack}\nRichiede un server didattico già avviato sul loopback e porta distinta. npm install, npm test, npm run seed, npm run reserve -- keyboard 2. Il seed usa soltanto inserimento se assente e non ripristina automaticamente le scorte già consumate. Test del modello e adattatore simulato non equivalgono a test sul server.\n"}
    book.add("progetto-magazzino","Progetto completo: prenotazione atomica "+stack,"Validare uno SKU, decrementare solo quantità disponibili e distinguere test del modello da integrazione con il server.",files,project=True,section="Inizializzazione",commands="npm install\nnpm test\nnpm run seed\nnpm run reserve -- keyboard 2",explanation="## Progetto\nI file mantengono separati validazione, connessione, operazione atomica e CLI. La URL è accettata soltanto per il protocollo/loopback/porta del laboratorio. Il database o prefisso dei dati è dedicato a questo capstone. Non sono incluse credenziali.\n\n## Prova\nEsegui npm test prima di usare il server: copre input e risposte simulate. Su un server locale nuovo esegui seed e poi reserve keyboard2: la quantità8 deve diventare6. Ripetendo consuma altre unità, mentre quantità insufficiente produce errore e non va trattata come successo.\n\n## Confine\nMongoDB usa un singolo findOneAndUpdate condizionale; Redis esegue controllo e DECRBY nello stesso script Lua. Queste operazioni evitano il read-then-write nel client. Nessuna esecuzione del server viene attestata se il report dichiara l'ambiente assente.",expected="Cinque test del modello/adattatore passano; sul server dedicato lo stock8 diventa6 con prenotazione2.",tags=[stack,"project","atomic","inventory","validation","node:test"])

def build_all():
    assert len(MONGO)==19 and len(REDIS)==19
    mongo=Book('mongodb','MongoDB Community8.0;mongosh2.x;Node driver7.7.0',["https://www.mongodb.com/docs/mongodb-shell/","https://www.mongodb.com/docs/manual/reference/method/db.collection.findOneAndUpdate/","https://www.mongodb.com/docs/drivers/node/current/"],"Server didattico separato su127.0.0.1:27018 e mongosh2.x. Ogni ricetta ricrea items nel proprio database atlas_demo_*. Nessun server viene avviato o collegato dal generatore.")
    mongo_lifecycle(mongo)
    for key,title,desc,op,expected in MONGO:
        mongo.add(key,title,desc,{"demo.js":mongo_source(key,op)},section="Database",commands=f'mongosh "mongodb://127.0.0.1:27018/atlas_demo_{key.replace("-","_")}" --quiet --file demo.js',explanation=f"## Operazione\n{desc}\n\n## Dataset e reset\ndemo.js sceglie il proprio database atlas_demo_{key.replace('-','_')}, elimina la sola collezione items e inserisce tre prodotti sintetici. Gli oggetti aggiuntivi, quando previsti, sono nominati nello stesso database. Usa soltanto il processo di laboratorio.\n\n## Controllo\n{expected}\n\n## Compatibilità\nEsempio MongoDB8.0 tramite mongosh; non è SQL e non va eseguito nel client MySQL. La validazione JavaScript non attesta l'esecuzione sul server.",expected=expected,tags=['mongodb',key,'mongosh','CRUD'],errors=['Connection refused: avviare manualmente il processo dedicato, senza cambiare URL verso un database reale.','Namespace o indice già esistente: controllare il reset della collezione del solo laboratorio.'])
    capstone(mongo,'mongodb');assert len(mongo.recipes)==25;save_book(mongo)
    redis=Book('redis','Redis Open Source8.2;redis-cli;Node client6.3.1',["https://redis.io/docs/latest/develop/get-started/","https://redis.io/commands/","https://redis.io/docs/latest/develop/clients/nodejs/"],"Redis8.2 e redis-cli in Linux/WSL, server didattico su127.0.0.1:6381. Le ricette toccano solo prefissi atlas_demo propri; non usano FLUSHALL o FLUSHDB.",os=['Linux'],ide=['VS Code','WSL'])
    redis_lifecycle(redis)
    for key,title,desc,body,expected in REDIS:
        redis.add(key,title,desc,{"demo.sh":redis_script(key,body)},section="Database",commands=[{'shell':'Bash','os':'Linux','cwd':'.','code':'bash ./demo.sh'}],explanation=f"## Operazione\n{desc}\n\n## Ambiente\nEsegui demo.sh in Bash dopo avere predisposto il processo didattico su6381. Il prefisso atlas_demo:{key} isola i nomi; DEL rimuove soltanto chiavi esplicite di questa prova. La funzione cli usa --raw per risultati semplici da leggere.\n\n## Controllo\n{expected}\n\n## Connessioni\nOgni chiamata cli apre una connessione. Le operazioni che richiedono una sessione unica usano un solo redis-cli con heredoc, come MULTI/EXEC. Nessuna esecuzione Redis reale è attestata dal solo parse della shell.",expected=expected,tags=['redis',key,'redis-cli','data structures'],errors=['Connection refused: verificare il server locale di prova e la porta6381.','WRONGTYPE: controllare TYPE sul nome della chiave; i laboratori usano prefissi separati.'])
    capstone(redis,'redis');assert len(redis.recipes)==25;save_book(redis)

if __name__=='__main__':build_all()
